CREATE TABLE v33525 (v33526 INT, v33527 VARCHAR(10), v33528 VARCHAR(400), v33529 VARCHAR(20), v33530 INT, v33531 VARCHAR(20), CONSTRAINT x7 CHECK (v33529 <> 0), CONSTRAINT x8 CHECK (v33530 LIKE 'j%'), CONSTRAINT x9 CHECK (LOWER(v33528) <> 'x'), CONSTRAINT x10 CHECK (REGEXP_LIKE(v33531, '@')), CONSTRAINT x11 CHECK (v33526 BETWEEN 5000 AND 20000), CONSTRAINT x12 CHECK (v33527 IN ('usa', 'uk'))) ENGINE=MyISAM